using System;

[AttributeUsage(AttributeTargets.All, AllowMultiple = true)]
public class Att : Attribute
{
    [Obsolete("Constructor", true)]
    public Att() { }
    [Obsolete("Property", true)]
    public int Prop
    {
        get { return 1; }
        set { }
    }
    [Obsolete("Property", true)]
    public int Prop2
    {
        get; set;
    }
    public int Prop3
    {
        get; [Obsolete("setter", true)]set;
    }
    [Obsolete("Property", true)]
    public int Prop4
    {
        get; [Obsolete("setter", true)]set;
    }
    public int Prop5
    {
        [Obsolete("setter", true)]get; set;
    }
    [Obsolete("Field", true)]
    public int Field;
}

[Att]
[Att(Field = 1)]
[Att(Prop = 1)]
[Att(Prop2 = 1)]
[Att(Prop3 = 1)]
[Att(Prop4 = 1)]
[Att(Prop5 = 1)]
public class Test
{
    [Att()]
    public static void Main() { }
}

